import { spawnSync } from 'node:child_process';
import { accessSync, constants, statSync } from 'node:fs';
import { join, resolve, sep } from 'node:path';

export const REFUSED = 2;

/** Resolve a plugin name to its script path. */
export function pluginPath(root, name) {
  return join(root, 'plugins', `${name}.sh`);
}

function refuse(name) {
  process.stderr.write(`plugin ${name} is not available\n`);
  return REFUSED;
}

/** Run a plugin, returning its exit code. */
export function runPlugin(root, name, args = []) {
  const pluginsDir = resolve(root, 'plugins');
  const script = resolve(pluginPath(root, name));

  // Refuse anything that would escape the plugins directory (e.g. `../secret`).
  if (script !== pluginsDir && !script.startsWith(pluginsDir + sep)) {
    return refuse(name);
  }

  let stat;
  try {
    stat = statSync(script);
  } catch {
    return refuse(name);
  }
  if (!stat.isFile()) {
    return refuse(name);
  }
  try {
    accessSync(script, constants.R_OK);
  } catch {
    return refuse(name);
  }

  const run = spawnSync('bash', [script, ...args], { encoding: 'utf8' });
  if (run.error) {
    return refuse(name);
  }
  if (run.stdout) process.stdout.write(run.stdout);
  if (run.stderr) process.stderr.write(run.stderr);
  return run.status ?? refuse(name);
}

