  }
  if (!stat.isFile()) {
    return refuse(name);
  }
  try {
    accessSync(script, constants.R_OK);
  } catch {
    return refuse(name);
  }

  const run = spawnSync('bash', [script, ...args], { encoding: 'utf8' });
  if (run.error) {
    return refuse(name);
