import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, writeFileSync, symlinkSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { runPlugin, REFUSED } from '../src/launcher.mjs';

const root = process.cwd();

function captureStderr(fn) {
  const original = process.stderr.write;
  let captured = '';
  process.stderr.write = (chunk) => {
    captured += chunk;
    return true;
  };
  try {
    const result = fn();
    return { result, stderr: captured };
  } finally {
    process.stderr.write = original;
  }
}

test('a working plugin runs and its exit code is 0', () => {
  assert.equal(runPlugin(root, 'hello'), 0);
});

test("a failing plugin's own exit code is propagated", () => {
  assert.equal(runPlugin(root, 'fails'), 7);
});

test('a plugin that does not exist is refused', () => {
  assert.equal(runPlugin(root, 'absent'), REFUSED);
});

test('a refusal names the plugin on stderr and exits 2', () => {
  const { result, stderr } = captureStderr(() => runPlugin(root, 'absent'));
  assert.equal(result, REFUSED);
  assert.match(stderr, /absent/);
});

test('a plugin name that would escape the plugins directory is refused', () => {
  const tmp = mkdtempSync(join(tmpdir(), 'launcher-test-'));
  mkdirSync(join(tmp, 'plugins'));
  const secret = join(tmp, 'secret.sh');
  writeFileSync(secret, '#!/bin/bash\necho "should never run" > "$(dirname "$0")/ran.marker"\n');

  const { result } = captureStderr(() => runPlugin(tmp, '../secret'));
  assert.equal(result, REFUSED);
  assert.throws(() => require('node:fs').statSync(join(tmp, 'ran.marker')));
});

test('a plugin path that is a directory rather than a file is refused', () => {
  const tmp = mkdtempSync(join(tmpdir(), 'launcher-test-'));
  mkdirSync(join(tmp, 'plugins'));
  mkdirSync(join(tmp, 'plugins', 'dirplugin.sh'));

  const { result, stderr } = captureStderr(() => runPlugin(tmp, 'dirplugin'));
  assert.equal(result, REFUSED);
  assert.match(stderr, /dirplugin/);
});

test('a plugin script that is a dangling symlink is refused', () => {
  const tmp = mkdtempSync(join(tmpdir(), 'launcher-test-'));
  mkdirSync(join(tmp, 'plugins'));
  symlinkSync(join(tmp, 'plugins', 'nowhere'), join(tmp, 'plugins', 'broken.sh'));

  const { result, stderr } = captureStderr(() => runPlugin(tmp, 'broken'));
  assert.equal(result, REFUSED);
  assert.match(stderr, /broken/);
});

test('a plugin that fails to spawn is refused, not left to crash the launcher', () => {
  const originalPath = process.env.PATH;
  process.env.PATH = '';
  try {
    const { result, stderr } = captureStderr(() => runPlugin(root, 'hello'));
    assert.equal(result, REFUSED);
    assert.match(stderr, /hello/);
  } finally {
    process.env.PATH = originalPath;
  }
});

